// Control: topic "resync" (desde el normalizer) o "reconnect" (inject manual).
// Los frames NO pasan por aquí: salen directo del callback ws.on("message") definido en "On Start".
const A = globalThis.__WAVE_ADAPTER__;
if (A) A.control(msg);
return null;

