        }
        if (checkCross(c, book)) return;
        const ts = num(d.ts);
        if (ts === null || ts >= OK.bboTs) {
            bboFromBook(book);
            if (ts !== null) OK.bboTs = ts;
        }
        emitEvents(c, t, 'book', [makeBook('depth', depthFromBook(book), ts, t)]);
