// Event-driven: cada mensaje del tap avanza el reloj de muestreo/cierre y luego se aplica.
// La salida humana (cada 5 s) la genera un timer en "On Start" que sólo LEE acumuladores.
globalThis.__WAVE_TEST__.onMsg(msg);
return null;

initialize:
// =====================================================================
// WAVE_TEST_V1 · WAVE TEST EVAL
// ---------------------------------------------------------------------
// ¿Tiene WAVE poder predictivo? Mide, sin look-ahead, qué hace el mid de
// Binance tras cada observación direccional de WAVE.
//
// ENTRADA: copia (tap) de los mensajes que los 4 NORMALIZER envían al
//          WAVE RAW ENGINE: { kind:'events'|'conn'|'nstats', exchange, t_recv, payload }
// SEÑAL  : muestreo en una grilla fija de 250 ms (reloj local). En cada borde T:
//          A = ALL.delta_usd_250ms (flujo agresor BUY-SELL consolidado, 250 ms)
//          dirección = signo(A): UP / DOWN / NEUTRAL (A = 0)
//          fuerza   = |A| en USD (bruta, SIEMPRE registrada)
//          + B, C, D, movimiento de precio, spread, etc. para reanálisis.
// PRECIO : mid = (best_bid + best_ask) / 2.  Principal: Binance.
//          Control: mediana de los retornos de mid de los exchanges disponibles.
// SIN LOOK-AHEAD: todo se rige por local_receive_timestamp (t_recv).
//          Antes de aplicar un mensaje con t_recv = x se ejecuta advance(x):
//            1) se toman las muestras de los bordes T < x
//            2) se cierran los horizontes con vencimiento T+h < x
//          con el estado que contiene SOLO eventos de t_recv <= T (o <= T+h).
//          REORDER BUFFER (250 ms): los mensajes del tap se acumulan en RAM ordenados
//          por t_recv y sólo se entregan cuando t_recv <= watermark = now - 250 ms.
//          Así advance()/apply() ven un stream ESTRICTAMENTE ordenado por t_recv.
//          Un timer de 50 ms mueve el watermark aunque el feed se detenga.
//          Un mensaje que llega con t_recv <= watermark (ya entregado) NO se inserta
//          en ventanas ya procesadas: se cuenta como late_beyond_buffer y se descarta
//          sólo en el TEST. Nunca se usa un evento posterior al instante medido.
// Todo en RAM. Sin disco, sin DB, sin context store, sin órdenes.
// =====================================================================
const EXCHANGES = ['binance', 'coinbase', 'kraken', 'okx'];
const WINDOWS = [100, 250, 500, 1000];    // mismas ventanas que el WAVE RAW ENGINE
const RES_CAP = 2048;                     // requerido por Stat (copiado del engine)
const SAMPLE_MS = 250;                    // 1 observación por intervalo de 250 ms
const HORIZONS = [100, 250, 500, 1000, 2000, 5000];
const HKEYS = ['100ms', '250ms', '500ms', '1s', '2s', '5s'];
const REF_EX = 'binance';                 // precio objetivo principal
const REF_STALE_MS = 2000;                // mid con más de 2 s sin update => no válido
const WARMUP_MS = 2000;                   // las ventanas necesitan llenarse
const TICK_MS = 50;                       // timer: mueve el watermark aunque no lleguen eventos
const REORDER_MS = 250;                   // reorder buffer: retraso de entrega al evaluador
const REORDER_CAP = 50000;                // tope duro de mensajes en el buffer (sólo ante anomalías)
const LAT_CAP = 4096;                     // reservoir para p50/p95/p99 de lateness
const MAX_CATCHUP = 40;                   // máx. bordes a recuperar de golpe (10 s)
const MAX_PENDING = 400;                  // tope duro de la cola de señales pendientes
const REPORT_MS = 5000;                   // salida humana cada 5 s
const AGG_CAP = 4096;                     // reservoir para mediana/p25/p75 (media y conteos exactos)
const TERCILE_MIN_N = 60;                 // mínimo de señales previas para terciles provisionales
const RING_SAMPLES = 2000;                // últimas observaciones guardadas para DUMP
const TIE_EPS = 1e-6;                     // |retorno| < 1e-6 bps => tie (mid sin cambio)
const W250 = WINDOWS.indexOf(250);
const MID_HIST_MS = 1500;                 // historia de mids de Binance para movimientos previos
const MID_HIST_CAP = 5000;                // tope duro de esa historia

// ======== CÓDIGO COPIADO LITERALMENTE DEL WAVE RAW ENGINE (ventanas) ========
function r(x, d) {
    if (x === null || x === undefined || !isFinite(x)) return null;
    const k = Math.pow(10, d === undefined ? 2 : d);
    return Math.round(x * k) / k;
}

// ---------- estadística por segundo: exacta en n/mean/min/max, percentiles por reservoir ----------
function Stat() { this.reset(); }
Stat.prototype.reset = function () { this.n = 0; this.sum = 0; this.min = Infinity; this.max = -Infinity; this.res = []; };
Stat.prototype.add = function (v) {
    if (!isFinite(v)) return;
    this.n++; this.sum += v;
    if (v < this.min) this.min = v;
    if (v > this.max) this.max = v;
    if (this.res.length < RES_CAP) this.res.push(v);
    else { const j = Math.floor(Math.random() * this.n); if (j < RES_CAP) this.res[j] = v; }
};
Stat.prototype.summary = function (d) {
    if (!this.n) return null;
    const a = this.res.slice().sort(function (x, y) { return x - y; });
    const q = function (p) { return a[Math.min(a.length - 1, Math.round(p * (a.length - 1)))]; };
    return { n: this.n, mean: r(this.sum / this.n, d), p50: r(q(0.5), d), p95: r(q(0.95), d), min: r(this.min, d), max: r(this.max, d) };
};

// ---------- deque O(1) amortizado sobre array con cabeza móvil ----------
function Deque() { this.a = []; this.h = 0; }
Deque.prototype.len = function () { return this.a.length - this.h; };
Deque.prototype.push = function (x) { this.a.push(x); };
Deque.prototype.front = function () { return this.a[this.h]; };
Deque.prototype.back = function () { return this.a[this.a.length - 1]; };
Deque.prototype.shift = function () { const x = this.a[this.h]; this.a[this.h++] = undefined; return x; };
Deque.prototype.pop = function () { return this.a.pop(); };
Deque.prototype.compact = function () {
    if (this.h > 1024 && this.h * 2 > this.a.length) { this.a = this.a.slice(this.h); this.h = 0; }
};

// ---------- ventana móvil de trades ----------
// sumas incrementales + deques monótonos para max/min intraventana (O(1) amortizado)
function TradeWin(ms) {
    this.ms = ms; this.q = new Deque(); this.mx = new Deque(); this.mn = new Deque();
    this.n = 0; this.frames = 0; this.usd = 0; this.buy = 0; this.sell = 0; this.ref = null;
}
TradeWin.prototype.push = function (rec) {
    this.q.push(rec);
    this.n++; this.usd += rec.usd;
    if (rec.s > 0) this.buy += rec.usd; else if (rec.s < 0) this.sell += rec.usd;
    if (rec.f) this.frames++;
    if (rec.p !== null) {
        while (this.mx.len() && this.mx.back().p <= rec.p) this.mx.pop();
        this.mx.push(rec);
        while (this.mn.len() && this.mn.back().p >= rec.p) this.mn.pop();
        this.mn.push(rec);
    }
};
TradeWin.prototype.evict = function (now) {
    const cut = now - this.ms, q = this.q;
    while (q.len() && q.front().t <= cut) {
        const x = q.shift();
        this.n--; this.usd -= x.usd;
        if (x.s > 0) this.buy -= x.usd; else if (x.s < 0) this.sell -= x.usd;
        if (x.f) this.frames--;
        if (x.p !== null) this.ref = x.p; // precio vigente al inicio de la ventana
        if (this.mx.len() && this.mx.front() === x) this.mx.shift();
        if (this.mn.len() && this.mn.front() === x) this.mn.shift();
    }
    if (this.n === 0) { this.usd = 0; this.buy = 0; this.sell = 0; this.frames = 0; } // sin deriva de coma flotante
    q.compact(); this.mx.compact(); this.mn.compact();
};
TradeWin.prototype.metrics = function (last, withPrice) {
    const s = this.ms / 1000;
    const o = {
        msgs: this.frames, trades: this.n, tps: r(this.n / s, 1),
        usd: r(this.usd, 0), buy_usd: r(this.buy, 0), sell_usd: r(this.sell, 0), delta_usd: r(this.buy - this.sell, 0)
    };
    if (!withPrice) return o;
    const ref = this.ref !== null ? this.ref : (this.q.len() ? this.q.front().p : null);
    if (ref === null || last === null || !(ref > 0)) {
        o.move_bps = null; o.max_up_bps = null; o.max_dn_bps = null; o.range_bps = null;
        return o;
    }
    const hi = Math.max(ref, this.mx.len() ? this.mx.front().p : ref);
    const lo = Math.min(ref, this.mn.len() ? this.mn.front().p : ref);
    o.move_bps = r((last - ref) / ref * 1e4, 2);
    o.max_up_bps = r((hi - ref) / ref * 1e4, 2);
    o.max_dn_bps = r((lo - ref) / ref * 1e4, 2);
    o.range_bps = r((hi - lo) / ref * 1e4, 2);
    return o;
};

function TradeStream() { this.wins = WINDOWS.map(function (ms) { return new TradeWin(ms); }); this.last = null; this.total = 0; this.usdTotal = 0; }
TradeStream.prototype.push = function (rec) {
    for (const w of this.wins) { w.push(rec); w.evict(rec.t); }
    if (rec.p !== null) this.last = rec.p;
    this.total++; this.usdTotal += rec.usd;
};
TradeStream.prototype.evict = function (now) { for (const w of this.wins) w.evict(now); };

// ---------- estado del libro por exchange + velocidad del imbalance ----------
function BookWin(ms) { this.ms = ms; this.q = new Deque(); this.n = 0; this.ref1 = null; this.ref10 = null; }
BookWin.prototype.evict = function (now) {
    const cut = now - this.ms;
    while (this.q.len() && this.q.front().t <= cut) {
        const x = this.q.shift();
        this.n--; this.ref1 = x.i1; this.ref10 = x.i10;
    }
    this.q.compact();
};

function imb(b, a) { return (b !== null && a !== null && b + a > 0) ? (b - a) / (b + a) : null; }

function BookState() {
    this.bid = null; this.bq = null; this.ask = null; this.aq = null;
    this.b5 = null; this.a5 = null; this.b10 = null; this.a10 = null;
    this.i1 = null; this.i5 = null; this.i10 = null; this.total = 0; this.channels = {};
    this.wins = WINDOWS.map(function (ms) { return new BookWin(ms); });
}
BookState.prototype.push = function (ev, t) {
    if (ev.best_bid !== null && ev.best_ask !== null) {
        this.bid = ev.best_bid; this.bq = ev.best_bid_qty; this.ask = ev.best_ask; this.aq = ev.best_ask_qty;
    }
    if (ev.bid_qty5 !== null && ev.ask_qty5 !== null) { this.b5 = ev.bid_qty5; this.a5 = ev.ask_qty5; }
    if (ev.bid_qty10 !== null && ev.ask_qty10 !== null) { this.b10 = ev.bid_qty10; this.a10 = ev.ask_qty10; }
    this.i1 = imb(this.bq, this.aq);
    this.i5 = imb(this.b5, this.a5);
    this.i10 = imb(this.b10, this.a10);
    this.total++;
    this.channels[ev.channel] = (this.channels[ev.channel] || 0) + 1;
    const smp = { t: t, i1: this.i1, i10: this.i10 };
    for (const w of this.wins) { w.q.push(smp); w.n++; w.evict(t); }
};
BookState.prototype.evict = function (now) { for (const w of this.wins) w.evict(now); };
BookState.prototype.clear = function () {
    this.bid = this.bq = this.ask = this.aq = null;
    this.b5 = this.a5 = this.b10 = this.a10 = null;
    this.i1 = this.i5 = this.i10 = null;
};
BookState.prototype.spreadBps = function () {
    if (this.bid === null || this.ask === null) return null;
    const mid = (this.bid + this.ask) / 2;
    return mid > 0 ? (this.ask - this.bid) / mid * 1e4 : null;
};
BookState.prototype.winMetrics = function (w) {
    const s = w.ms / 1000;
    const ref1 = w.ref1 !== null ? w.ref1 : (w.q.len() ? w.q.front().i1 : null);
    const ref10 = w.ref10 !== null ? w.ref10 : (w.q.len() ? w.q.front().i10 : null);
    return {
        updates: w.n, ups: r(w.n / s, 1),
        imb_vel_per_s: (ref1 !== null && this.i1 !== null) ? r((this.i1 - ref1) / s, 3) : null,
        imb10_vel_per_s: (ref10 !== null && this.i10 !== null) ? r((this.i10 - ref10) / s, 3) : null
    };
};
// ======================= fin del código copiado ============================

function sgn(x) { return x > 0 ? 1 : (x < 0 ? -1 : 0); }

function medianOf(a) {
    if (!a.length) return null;
    const v = a.slice().sort(function (x, y) { return x - y; });
    const m = v.length >> 1;
    return v.length % 2 ? v[m] : (v[m - 1] + v[m]) / 2;
}

// ---------- acumulador de resultados por horizonte/grupo ----------
function Agg() { this.n = 0; this.sum = 0; this.hits = 0; this.misses = 0; this.ties = 0; this.res = []; }
Agg.prototype.add = function (v) {
    this.n++; this.sum += v;
    if (Math.abs(v) < TIE_EPS) this.ties++; else if (v > 0) this.hits++; else this.misses++;
    if (this.res.length < AGG_CAP) this.res.push(v);
    else { const j = Math.floor(Math.random() * this.n); if (j < AGG_CAP) this.res[j] = v; }
};
Agg.prototype.summary = function () {
    const dec = this.hits + this.misses;
    const o = {
        n_valid: this.n, hits: this.hits, misses: this.misses, ties: this.ties,
        hit_rate_pct: dec ? r(this.hits / dec * 100, 1) : null,
        tie_rate_pct: this.n ? r(this.ties / this.n * 100, 1) : null,
        mean_signed_bps: this.n ? r(this.sum / this.n, 3) : null,
        median_signed_bps: null, p25_signed_bps: null, p75_signed_bps: null
    };
    if (this.res.length) {
        const a = Float64Array.from(this.res).sort();
        const q = function (p) { return a[Math.min(a.length - 1, Math.round(p * (a.length - 1)))]; };
        o.median_signed_bps = r(q(0.5), 3); o.p25_signed_bps = r(q(0.25), 3); o.p75_signed_bps = r(q(0.75), 3);
    }
    return o;
};

function newResults(groups) {
    const o = {};
    for (const k of HKEYS) { o[k] = {}; for (const g of groups) o[k][g] = new Agg(); }
    return o;
}

const PRIMARY_GROUPS = ['all', 'up', 'down', 'weak', 'medium', 'strong'];

function newState() {
    const now = Date.now();
    const S = {
        t0: now, startT: now, nextT: Math.ceil(now / SAMPLE_MS) * SAMPLE_MS, lastAdv: 0, seq: 0,
        ex: {}, all: new TradeStream(),
        q: [], head: 0, ptr: HORIZONS.map(function () { return 0; }),
        ring: [], strength: new Agg(), terc: null,
        primary: newResults(PRIMARY_GROUPS),
        secondary: newResults(['all', 'up', 'down']),
        baseline: newResults(['all']),
        c: {
            n_total_samples: 0, n_warmup: 0, n_skipped_intervals: 0,
            n_directional: 0, n_up: 0, n_down: 0, n_neutral: 0,
            n_no_ref: 0, n_evaluated: 0,
            pending_max_seen: 0, pending_dropped: 0, horizons_expired: 0, late_events: 0,
            reorder_buffer_max: 0, late_beyond_buffer: 0, out_of_order_events: 0, reorder_forced: 0, reorder_delivered: 0,
            invalid_ref_by_h: {}, invalid_sec_by_h: {}
        }
    };
    for (const k of HKEYS) { S.c.invalid_ref_by_h[k] = 0; S.c.invalid_sec_by_h[k] = 0; }
    for (const e of EXCHANGES) S.ex[e] = { trades: new TradeStream(), book: new BookState(), bookT: 0 };
    // reorder buffer: [{t, seq, msg}] ordenado por (t_recv, orden de llegada)
    S.rb = { a: [], h: 0, seq: 0, wm: 0, maxSeen: 0, lateness: new LatStat(), arrival: new LatStat() };
    S.midHist = new Deque(); // [{t, mid}] de Binance, para el movimiento de mid ANTES de t0
    return S;
}

let S = newState();

// mid "as-of" el instante at: último mid conocido, si es reciente
function midOf(e, at) {
    const X = S.ex[e];
    const b = X.book;
    if (b.bid === null || b.ask === null || !X.bookT) return null;
    if (at - X.bookT > REF_STALE_MS) return null;
    return (b.bid + b.ask) / 2;
}

// mid de Binance as-of 'at' (último valor con t <= at) desde la historia
function binanceMidAt(at) {
    const a = S.midHist.a;
    let lo = S.midHist.h, hi = a.length - 1, ans = null;
    while (lo <= hi) {
        const m = (lo + hi) >> 1;
        if (a[m].t <= at) { ans = a[m]; lo = m + 1; } else hi = m - 1;
    }
    return ans ? ans.mid : null;
}

function pushBinanceMid(t) {
    const B = S.ex.binance.book;
    if (B.bid === null || B.ask === null) return;
    const mid = (B.bid + B.ask) / 2;
    const H = S.midHist;
    if (H.len() && H.back().mid === mid) return;
    H.push({ t: t, mid: mid });
    // conservar MID_HIST_MS + el último valor anterior (es el "as-of" del borde de la ventana)
    while (H.len() > 1 && (H.a[H.h + 1].t <= t - MID_HIST_MS || H.len() > MID_HIST_CAP)) H.shift();
    H.compact();
}

function bps(a, b) { return (a !== null && b !== null && b > 0) ? r((a / b - 1) * 1e4, 3) : null; }

// =====================================================================
// MUESTRA en el borde t0 (estado = todos los eventos con t_recv <= t0)
// =====================================================================
function sample(T) {
    S.c.n_total_samples++;
    if (T - S.startT < WARMUP_MS) { S.c.n_warmup++; return; }
    for (const e of EXCHANGES) { S.ex[e].trades.evict(T); S.ex[e].book.evict(T); }
    S.all.evict(T);

    const wa = S.all.wins[W250];
    const A = wa.buy - wa.sell;
    const sg = A > 0 ? 1 : (A < 0 ? -1 : 0);
    const per = {};
    const imb10s = [];
    const movesByW = {};
    for (const ms of WINDOWS) movesByW[ms] = [];
    let breadth = 0, active = 0;
    const mids0 = {};
    for (const e of EXCHANGES) {
        const X = S.ex[e];
        const w = X.trades.wins[W250];
        const d = w.buy - w.sell;
        const B = X.book;
        const mid = midOf(e, T);
        if (w.n > 0) active++;
        if (sg !== 0 && sgn(d) === sg) breadth++;
        const mv = {};
        for (const tw of X.trades.wins) {
            const m = tw.metrics(X.trades.last, true).move_bps;  // misma definición que el engine
            mv[tw.ms] = m;
            if (m !== null) movesByW[tw.ms].push(m);
        }
        if (B.i10 !== null) imb10s.push(B.i10);
        if (mid !== null) mids0[e] = mid;
        per[e] = {
            delta_usd_250ms: r(d, 0), trades_250ms: w.n,
            price_move_100ms_bps: mv[100], price_move_250ms_bps: mv[250], price_move_500ms_bps: mv[500], price_move_1000ms_bps: mv[1000],
            mid: mid, spread_bps: r(B.spreadBps(), 3),
            imb1: r(B.i1, 4), imb5: r(B.i5, 4), imb10: r(B.i10, 4),
            imb_vel_250ms_per_s: B.winMetrics(B.wins[W250]).imb_vel_per_s,
            book_age_ms: X.bookT ? T - X.bookT : null, stale: mid === null
        };
    }
    const p0 = midOf(REF_EX, T);
    const bn = per.binance;
    const pre = {};
    for (const ms of WINDOWS) {
        pre['price_move_' + ms + 'ms_bps_binance'] = bn['price_move_' + ms + 'ms_bps'];
        pre['price_move_' + ms + 'ms_bps_median'] = r(medianOf(movesByW[ms]), 3);
        pre['binance_mid_move_' + ms + 'ms_bps'] = p0 === null ? null : bps(p0, binanceMidAt(T - ms));
    }
    const rec = {
        id: ++S.seq,
        t0: T,
        direction: sg > 0 ? 'UP' : (sg < 0 ? 'DOWN' : 'NEUTRAL'),
        sign: sg,
        delta_usd_250ms: r(A, 0),                                // A
        strength_abs_usd: r(Math.abs(A), 0),                     // fuerza bruta (siempre)
        buy_usd_250ms: r(wa.buy, 0),
        sell_usd_250ms: r(wa.sell, 0),
        usd_250ms: r(wa.usd, 0),
        trades_250ms: wa.n,
        delta_usd_100ms: r(S.all.wins[0].buy - S.all.wins[0].sell, 0),
        delta_usd_500ms: r(S.all.wins[2].buy - S.all.wins[2].sell, 0),
        delta_usd_1000ms: r(S.all.wins[3].buy - S.all.wins[3].sell, 0),
        flow_imbalance_250ms: wa.usd > 0 ? r(A / wa.usd, 4) : null,   // B
        breadth: breadth,                                        // C: exchanges con delta_250 del mismo signo
        active_exchanges: active,                                //    exchanges con trades en 250 ms
        book_imbalance: {                                        // D
            imb1_binance: bn.imb1, imb5_binance: bn.imb5, imb10_binance: bn.imb10,
            imb10_mean: imb10s.length ? r(imb10s.reduce(function (s, x) { return s + x; }, 0) / imb10s.length, 4) : null,
            imb_vel_250ms_per_s_binance: bn.imb_vel_250ms_per_s
        },
        spread_bps_binance: bn.spread_bps,
        pre_move: pre,                                           // movimiento YA ocurrido antes de t0
        exchanges: per,
        p0: p0, p0_age_ms: bn.book_age_ms,
        tercile_provisional: null,
        future: {},
        // internos
        _rnd: 0, _done: 0, _mids0: mids0
    };
    S.ring.push(rec);
    if (S.ring.length > RING_SAMPLES) S.ring.shift();

    if (sg === 0) { S.c.n_neutral++; return; }
    S.c.n_directional++;
    if (sg > 0) S.c.n_up++; else S.c.n_down++;
    // tercil PROVISIONAL con límites calculados sólo con señales anteriores
    if (S.terc) rec.tercile_provisional = rec.strength_abs_usd <= S.terc[0] ? 'weak' : (rec.strength_abs_usd <= S.terc[1] ? 'medium' : 'strong');
    S.strength.add(rec.strength_abs_usd);
    if (p0 === null) { S.c.n_no_ref++; return; }   // Binance stale/caído: no evaluable
    rec._rnd = Math.random() < 0.5 ? -1 : 1;         // baseline aleatoria (sanity check)
    S.c.n_evaluated++;
    S.q.push(rec);
    while (S.q.length - S.head > MAX_PENDING) dropOldest();
    const live = S.q.length - S.head;
    if (live > S.c.pending_max_seen) S.c.pending_max_seen = live;
}

// cierre del horizonte k de la señal s, con el estado as-of t0 + h
function resolve(s, k) {
    const key = HKEYS[k];
    const at = s.t0 + HORIZONS[k];
    const f = { p: null, ret_bps: null, signed_bps: null, outcome: null, sec_signed_bps: null };
    const p1 = midOf(REF_EX, at);
    if (p1 === null) {
        S.c.invalid_ref_by_h[key]++;
    } else {
        const ret = (p1 / s.p0 - 1) * 1e4;
        const signed = ret * s.sign;
        f.p = p1; f.ret_bps = r(ret, 3); f.signed_bps = r(signed, 3);
        f.outcome = Math.abs(signed) < TIE_EPS ? 'tie' : (signed > 0 ? 'hit' : 'miss');
        const P = S.primary[key];
        P.all.add(signed);
        P[s.sign > 0 ? 'up' : 'down'].add(signed);
        if (s.tercile_provisional) P[s.tercile_provisional].add(signed);
        S.baseline[key].all.add(ret * s._rnd);
    }
    // control secundario: mediana de retornos de mid por exchange (>= 2 exchanges no stale)
    const rets = [];
    for (const e of EXCHANGES) {
        const m0 = s._mids0[e];
        if (m0 === undefined) continue;
        const m1 = midOf(e, at);
        if (m1 !== null) rets.push((m1 / m0 - 1) * 1e4);
    }
    if (rets.length >= 2) {
        const v = medianOf(rets) * s.sign;
        f.sec_signed_bps = r(v, 3);
        S.secondary[key].all.add(v);
        S.secondary[key][s.sign > 0 ? 'up' : 'down'].add(v);
    } else {
        S.c.invalid_sec_by_h[key]++;
    }
    s.future[key] = f;
    s._done++;
}

// tope duro: descartar la señal pendiente más antigua (sólo ante anomalías)
function dropOldest() {
    const s = S.q[S.head];
    for (let k = 0; k < HORIZONS.length; k++) {
        if (S.ptr[k] <= S.head) { S.ptr[k] = S.head + 1; S.c.horizons_expired++; }
    }
    S.q[S.head] = undefined;
    S.head++;
    S.c.pending_dropped++;
    void s;
}

function advance(x) {
    S.lastAdv = x;
    if (x - S.nextT > MAX_CATCHUP * SAMPLE_MS) {   // salto de reloj / event loop bloqueado
        const skip = Math.floor((x - S.nextT) / SAMPLE_MS);
        S.c.n_skipped_intervals += skip;
        S.nextT += skip * SAMPLE_MS;
    }
    while (S.nextT < x) { sample(S.nextT); S.nextT += SAMPLE_MS; }
    // cerrar horizontes vencidos (cada puntero avanza en orden temporal)
    for (let k = 0; k < HORIZONS.length; k++) {
        const h = HORIZONS[k];
        while (S.ptr[k] < S.q.length && S.q[S.ptr[k]].t0 + h < x) { resolve(S.q[S.ptr[k]], k); S.ptr[k]++; }
    }
    // retirar las señales con todos sus horizontes cerrados
    while (S.head < S.q.length && S.q[S.head]._done >= HORIZONS.length) { S.q[S.head] = undefined; S.head++; }
    if (S.head > 512) {
        S.q = S.q.slice(S.head);
        for (let k = 0; k < S.ptr.length; k++) S.ptr[k] -= S.head;
        S.head = 0;
    }
}

// aplica eventos: mismas reglas que WAVE RAW ENGINE.onEvents (trades -> ventanas, book -> estado)
function apply(msg) {
    const X = S.ex[msg.exchange];
    if (!X) return;
    const t = msg.t_recv;
    const evs = msg.payload;
    let first = true;
    for (let i = 0; i < evs.length; i++) {
        const ev = evs[i];
        if (ev.kind === 'trade') {
            const rec = { t: t, p: ev.price, usd: ev.usd, s: ev.side === 'BUY' ? 1 : (ev.side === 'SELL' ? -1 : 0), f: first };
            first = false;
            X.trades.push(rec);
            S.all.push({ t: t, p: null, usd: rec.usd, s: rec.s, f: rec.f });
        } else if (ev.kind === 'book') {
            X.book.push(ev, t);
            X.bookT = t;
            if (X === S.ex.binance) pushBinanceMid(t);
        }
    }
}

// ---------- entrega al evaluador (lógica original de onMsg, ahora en orden estricto) ----------
function deliver(msg) {
    if (msg.kind === 'events') {
        const t = msg.t_recv;
        if (t > S.lastAdv) advance(t);
        else if (t < S.lastAdv) S.c.late_events++;   // con el reorder buffer debe quedar en 0
        apply(msg);
    } else if (msg.kind === 'conn') {
        const X = S.ex[msg.exchange];
        if (X && msg.conn === 'book' && msg.event === 'close') {
            X.book.clear(); X.bookT = 0;   // libro desconocido hasta el próximo snapshot => mid no válido
            if (X === S.ex.binance) { S.midHist = new Deque(); }
        }
    }
}

// ---------- reorder buffer ----------
// reservoir con generador propio (LCG): NO consume Math.random, así la secuencia aleatoria
// del evaluador (baseline) es exactamente la misma que sin reorder buffer
function LatStat() { this.n = 0; this.max = 0; this.res = []; this.rng = 12345; }
LatStat.prototype.add = function (v) {
    this.n++;
    if (v > this.max) this.max = v;
    if (this.res.length < LAT_CAP) this.res.push(v);
    else {
        this.rng = (Math.imul(this.rng, 1664525) + 1013904223) >>> 0;
        const j = this.rng % this.n;
        if (j < LAT_CAP) this.res[j] = v;
    }
};
LatStat.prototype.summary = function () {
    if (!this.n) return { n: 0, p50: null, p95: null, p99: null, max: null };
    const a = Float64Array.from(this.res).sort();
    const q = function (p) { return a[Math.min(a.length - 1, Math.round(p * (a.length - 1)))]; };
    return { n: this.n, p50: q(0.5), p95: q(0.95), p99: q(0.99), max: this.max };
};

function rbInsert(t, msg) {
    const R = S.rb;
    const now = Date.now();
    // lateness = cuánto llega "detrás" del t_recv más nuevo ya visto (0 si llega en orden)
    const late = t < R.maxSeen ? R.maxSeen - t : 0;
    if (t > R.maxSeen) R.maxSeen = t;
    R.lateness.add(late);
    R.arrival.add(Math.max(0, now - t));
    if (late > 0) S.c.out_of_order_events++;
    if (t <= R.wm) { S.c.late_beyond_buffer++; return; }   // ya entregado hasta el watermark: se descarta sólo en el TEST
    const it = { t: t, seq: ++R.seq, msg: msg };
    const a = R.a;
    let i = a.length;
    if (i === R.h || a[i - 1].t <= t) a.push(it);           // caso normal: llega en orden
    else {                                                  // inserción binaria por (t, seq)
        let lo = R.h, hi = i;
        while (lo < hi) { const m = (lo + hi) >> 1; if (a[m].t <= t) lo = m + 1; else hi = m; }
        a.splice(lo, 0, it);
    }
    const len = a.length - R.h;
    if (len > S.c.reorder_buffer_max) S.c.reorder_buffer_max = len;
    while (a.length - R.h > REORDER_CAP) {                  // tope duro: entregar el más viejo
        const x = a[R.h]; a[R.h] = undefined; R.h++;
        S.c.reorder_forced++;
        if (x.t > R.wm) R.wm = x.t;
        S.c.reorder_delivered++;
        deliver(x.msg);
    }
}

// entrega en orden todo lo que tenga t_recv <= W y luego avanza el reloj del evaluador hasta W
function flush(W) {
    const R = S.rb;
    if (W <= R.wm) return;
    const a = R.a;
    while (R.h < a.length && a[R.h].t <= W) {
        const x = a[R.h]; a[R.h] = undefined; R.h++;
        S.c.reorder_delivered++;
        deliver(x.msg);
    }
    R.wm = W;
    if (R.h > 4096 && R.h * 2 > a.length) { R.a = a.slice(R.h); R.h = 0; }
    if (W > S.lastAdv) advance(W);
}

function onMsg(msg) {
    if (!msg) return;
    if (msg.kind === 'events') {
        const t = msg.t_recv;
        if (typeof t !== 'number' || !Array.isArray(msg.payload)) return;
        rbInsert(t, msg);
        flush(Date.now() - REORDER_MS);
    } else if (msg.kind === 'conn') {
        rbInsert(typeof msg.t === 'number' ? msg.t : Date.now(), msg);   // ordenado con los eventos
        flush(Date.now() - REORDER_MS);
    } else if (msg.topic === 'reset') {
        S = newState();
        report();
    } else if (msg.topic === 'dump') {
        node.send([null, null, { topic: 'wave_test_v1/samples', payload: S.ring.map(compactRec) }], false);
    }
}

function compactRec(s) {
    const o = {};
    for (const k in s) if (k.charAt(0) !== '_') o[k] = s[k];
    return o;
}

// =====================================================================
// SALIDA HUMANA cada 5 s (sólo lectura de acumuladores)
// =====================================================================
function fmtH(sm) {
    if (!sm || !sm.n_valid) return 'n/a';
    const m = sm.mean_signed_bps;
    return (m >= 0 ? '+' : '') + m.toFixed(2) + 'bps ' + (sm.hit_rate_pct === null ? '-' : sm.hit_rate_pct.toFixed(1) + '%') + ' t' + sm.tie_rate_pct.toFixed(0) + '%';
}

function report() {
    const now = Date.now();
    // terciles provisionales: límites desde TODAS las señales previas (ventana expansiva)
    if (S.strength.n >= TERCILE_MIN_N) {
        const a = Float64Array.from(S.strength.res).sort();
        const q = function (p) { return a[Math.min(a.length - 1, Math.round(p * (a.length - 1)))]; };
        S.terc = [q(1 / 3), q(2 / 3)];
    }
    const primary = {}, secondary = {}, baseline = {};
    for (const k of HKEYS) {
        primary[k] = {};
        for (const g of PRIMARY_GROUPS) primary[k][g] = S.primary[k][g].summary();
        secondary[k] = { all: S.secondary[k].all.summary(), up: S.secondary[k].up.summary(), down: S.secondary[k].down.summary() };
        baseline[k] = S.baseline[k].all.summary();
    }
    let dist = null;
    if (S.strength.res.length) {
        const a = Float64Array.from(S.strength.res).sort();
        const q = function (p) { return r(a[Math.min(a.length - 1, Math.round(p * (a.length - 1)))], 0); };
        dist = { n: S.strength.n, p10: q(0.1), p25: q(0.25), p50: q(0.5), p75: q(0.75), p90: q(0.9), p99: q(0.99), max: q(1) };
    }
    const c = S.c;
    const detail = {
        ts: now, iso: new Date(now).toISOString(), uptime_s: Math.round((now - S.t0) / 1000),
        config: { sample_ms: SAMPLE_MS, horizons: HKEYS, reference: 'binance_mid', secondary: 'median_mid_return_all_exchanges',
            signal: 'sign(ALL.delta_usd_250ms)', strength: 'abs(ALL.delta_usd_250ms)', ref_stale_ms: REF_STALE_MS, tie_eps_bps: TIE_EPS },
        counts: {
            n_total_samples: c.n_total_samples, n_warmup: c.n_warmup, n_skipped_intervals: c.n_skipped_intervals,
            n_directional: c.n_directional, n_up: c.n_up, n_down: c.n_down, n_neutral: c.n_neutral,
            n_no_ref: c.n_no_ref, n_evaluated: c.n_evaluated,
            n_valid_by_h: HKEYS.reduce(function (o, k) { o[k] = S.primary[k].all.n; return o; }, {}),
            invalid_ref_by_h: c.invalid_ref_by_h, invalid_secondary_by_h: c.invalid_sec_by_h
        },
        queue: { pending: S.q.length - S.head, pending_max_seen: c.pending_max_seen, max_pending: MAX_PENDING,
            pending_dropped: c.pending_dropped, horizons_expired: c.horizons_expired, late_events: c.late_events,
            reorder_buffer_ms: REORDER_MS, reorder_buffer_current: S.rb.a.length - S.rb.h, reorder_buffer_max: c.reorder_buffer_max,
            late_beyond_buffer: c.late_beyond_buffer, out_of_order_events: c.out_of_order_events,
            reorder_forced: c.reorder_forced, reorder_delivered: c.reorder_delivered,
            watermark_lag_ms: S.rb.wm ? now - S.rb.wm : null,
            lateness_ms: S.rb.lateness.summary(), arrival_delay_ms: S.rb.arrival.summary() },
        strength: { field: 'abs(ALL.delta_usd_250ms)', unit: 'USD', distribution: dist,
            terciles_provisional: { thresholds_usd: S.terc ? [r(S.terc[0], 0), r(S.terc[1], 0)] : null,
                note: 'límites expansivos que cambian durante la corrida: sólo diagnóstico, NO prueba de monotonía' } },
        primary_binance_mid: primary,
        secondary_median_mid: secondary,
        baseline_random_direction: baseline,
        last_samples: S.ring.slice(-3).map(compactRec)
    };
    const line = 'WAVE TEST | n=' + c.n_total_samples + ' dir=' + c.n_directional + ' eval=' + c.n_evaluated +
        HKEYS.map(function (k) { return ' | ' + k + ' ' + fmtH(primary[k].all); }).join('');
    node.send([{ topic: 'wave_test_v1/line', payload: line }, { topic: 'wave_test_v1/detail', payload: detail }, null], false);
    node.status({ fill: 'green', shape: 'dot', text: 'n=' + c.n_total_samples + ' dir=' + c.n_directional + ' pend=' + (S.q.length - S.head) });
}

const tick = setInterval(function () {
    flush(Date.now() - REORDER_MS);   // vacía el buffer y mueve el reloj aunque el feed se detenga
}, TICK_MS);
const rep = setInterval(report, REPORT_MS);

globalThis.__WAVE_TEST__ = { onMsg: onMsg, stop: function () { clearInterval(tick); clearInterval(rep); } };

func:
// Recibe: export / export_auto (injects), detalle 5 s y DUMP de WAVE TEST EVAL.
// Toda la lógica y la escritura (asíncrona) viven en "On Start".
globalThis.__WAVE_EXPORT__.onMsg(msg);
return null;

initialize:
// =====================================================================
// WAVE_TEST_V1 · WAVE TEST EXPORT
// ---------------------------------------------------------------------
// Exporta un reporte JSON completo para análisis externo.
// NO toca la lógica de WAVE TEST EVAL: sólo usa sus salidas existentes.
//   1) llega 'export' (inject manual) o 'export_auto' (inject cada 5 min)
//   2) espera el próximo DETALLE de EVAL (salida 2, cada 5 s) => counts/queue/stats frescos
//   3) pide un DUMP a EVAL (topic 'dump') => muestras del mismo instante (±ms)
//   4) arma el reporte con las últimas 500 muestras y lo escribe de forma ASÍNCRONA
//      y por partes (cede el event loop entre bloques): nunca en la ruta de eventos.
// Escritura atómica: <archivo>.tmp -> fsync -> rename.
//   WAVE_TEST_LATEST.json                    (manual y automático, se sobreescribe)
//   WAVE_TEST_YYYY-MM-DD_HH-mm-ss.json       (sólo manual; se conservan los últimos 100)
// Salidas: 1 -> EVAL (pedido de dump) · 2 -> Debug DUMP manual (reenvío) · 3 -> Debug estado del export
//          4 -> WAVE LAB STORE (toda muestra recibida, sin clonar; sólo lectura)
// El inject DUMP SAMPLES pasa por aquí (topic 'dump') para que sólo los DUMP manuales lleguen al Debug.
// =====================================================================
// directorio de reportes (override opcional: variable de entorno WAVE_REPORT_DIR)
const REPORT_DIR = env.get('WAVE_REPORT_DIR') || '/home/plapopepo/wave_reports';
const LATEST_NAME = 'WAVE_TEST_LATEST.json';
const HIST_PREFIX = 'WAVE_TEST_';
const HIST_RE = /^WAVE_TEST_\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}\.json$/;
const MAX_HISTORY = 100;
const N_SAMPLES = 500;
const CHUNK = 50;                 // muestras serializadas por bloque antes de ceder el event loop
const TIMEOUT_MS = 15000;         // detalle (<= 5 s) + dump deben llegar antes
const EXPORT_VERSION = 1;

const X = {
    lastDetail: null,
    job: null,                    // { trigger, phase: 'wait_detail'|'wait_dump'|'writing', t, timer }
    busy: false,
    manualDump: false,            // DUMP SAMPLES pedido a mano => su respuesta va al Debug
    stats: { ok: 0, failed: 0, skipped_busy: 0, last_file: null, last_bytes: null, last_ms: null, last_error: null }
};

const pad = (n) => (n < 10 ? '0' : '') + n;
function stamp(d) {   // hora local del miniPC
    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + '_' + pad(d.getHours()) + '-' + pad(d.getMinutes()) + '-' + pad(d.getSeconds());
}
const yieldLoop = () => new Promise((res) => setTimeout(res, 0)); // setImmediate no existe en el sandbox del Function node

function status(fill, text) { node.status({ fill: fill, shape: 'dot', text: text }); }
function report(o) { node.send([null, null, { topic: 'wave_test_v1/export', payload: o }, null], false); }

function startJob(trigger) {
    if (X.job || X.busy) {
        X.stats.skipped_busy++;
        report({ ok: false, trigger: trigger, error: 'export en curso: pedido ignorado' });
        return;
    }
    X.job = { trigger: trigger, phase: 'wait_detail', t: Date.now() };
    X.job.timer = setTimeout(function () { failJob('timeout esperando detalle/dump de WAVE TEST EVAL'); }, TIMEOUT_MS);
    status('blue', 'export ' + trigger + ': esperando detalle');
}

function failJob(err) {
    const j = X.job;
    if (j && j.timer) clearTimeout(j.timer);
    X.job = null;
    X.stats.failed++;
    X.stats.last_error = err;
    status('red', 'export falló: ' + err);
    node.warn('[WAVE EXPORT] ' + err);
    report({ ok: false, trigger: j ? j.trigger : null, error: err });
}

function onDetail(d) {
    X.lastDetail = d;
    const j = X.job;
    if (j && j.phase === 'wait_detail') {
        j.phase = 'wait_dump';
        j.detail = d;
        node.send([{ topic: 'dump' }, null, null, null], false);   // EVAL responde por su salida 3
    }
}

function onSamples(msg) {
    node.send([null, null, null, msg], false);                // WAVE LAB: misma referencia, sin copia
    const j = X.job;
    if (!j || j.phase !== 'wait_dump') {
        if (X.manualDump) {                                   // DUMP manual: al Debug como antes
            X.manualDump = false;
            node.send([null, { topic: msg.topic, payload: msg.payload }, null, null], false);
        }
        return;
    }
    clearTimeout(j.timer);
    j.phase = 'writing';
    const all = Array.isArray(msg.payload) ? msg.payload : [];
    const samples = all.slice(-N_SAMPLES);
    X.job = null;
    X.busy = true;
    write(j, samples).then(function (res) {
        X.busy = false;
        X.stats.ok++;
        X.stats.last_file = res.file; X.stats.last_bytes = res.bytes; X.stats.last_ms = res.ms; X.stats.last_error = null;
        status('green', j.trigger + ' OK ' + Math.round(res.bytes / 1024) + ' KB · ' + res.ms + ' ms · ' + new Date().toLocaleTimeString());
        report(Object.assign({ ok: true, trigger: j.trigger }, res));
    }).catch(function (e) {
        X.busy = false;
        X.stats.failed++;
        X.stats.last_error = String(e && e.message || e);
        status('red', 'export falló: ' + X.stats.last_error);
        node.warn('[WAVE EXPORT] ' + X.stats.last_error);
        report({ ok: false, trigger: j.trigger, error: X.stats.last_error });
    });
}

// escribe en <final>.tmp, fsync, y recién entonces rename => nunca queda un JSON truncado
async function writeAtomic(finalPath, writer) {
    const tmp = finalPath + '.tmp';
    const fh = await fs.promises.open(tmp, 'w');
    let bytes = 0;
    try {
        await writer(async function (s) { await fh.write(s); bytes += Buffer.byteLength(s); });
        await fh.sync();
    } finally {
        await fh.close();
    }
    await fs.promises.rename(tmp, finalPath);
    return bytes;
}

async function write(j, samples) {
    const t0 = Date.now();
    const d = j.detail;
    const now = new Date();
    const head = {
        export_version: EXPORT_VERSION,
        generated_at: now.toISOString(),
        generated_at_local: stamp(now),
        trigger: j.trigger,
        uptime_s: d.uptime_s,
        detail_ts: d.ts,
        detail_iso: d.iso,
        config: d.config,
        counts: d.counts,
        queue: d.queue,
        strength: d.strength,
        primary_binance_mid: d.primary_binance_mid,
        secondary_median_mid: d.secondary_median_mid,
        baseline_random_direction: d.baseline_random_direction,
        samples_meta: {
            n: samples.length, max: N_SAMPLES,
            first_t0: samples.length ? samples[0].t0 : null,
            last_t0: samples.length ? samples[samples.length - 1].t0 : null,
            note: 'incluye muestras NEUTRAL; las más recientes pueden tener horizontes aún abiertos (future incompleto)'
        }
    };
    await fs.promises.mkdir(REPORT_DIR, { recursive: true });
    const latest = path.join(REPORT_DIR, LATEST_NAME);
    const bytes = await writeAtomic(latest, async function (put) {
        const h = JSON.stringify(head);
        await put(h.slice(0, -1) + ',"samples":[');
        for (let i = 0; i < samples.length; i += CHUNK) {
            const part = samples.slice(i, i + CHUNK).map(function (s) { return JSON.stringify(s); }).join(',');
            await put((i ? ',' : '') + part);
            await yieldLoop();                                 // cede el event loop entre bloques
        }
        await put(']}');
    });
    const res = { file: latest, bytes: bytes, samples: samples.length };
    if (j.trigger === 'manual') {
        const hist = path.join(REPORT_DIR, HIST_PREFIX + stamp(now) + '.json');
        await fs.promises.copyFile(latest, hist + '.tmp');
        await fs.promises.rename(hist + '.tmp', hist);
        res.history_file = hist;
        res.history_deleted = await prune();
    }
    res.ms = Date.now() - t0;
    return res;
}

// conserva sólo los últimos MAX_HISTORY históricos (orden por nombre = orden cronológico)
async function prune() {
    const names = (await fs.promises.readdir(REPORT_DIR)).filter(function (n) { return HIST_RE.test(n); }).sort();
    const extra = names.slice(0, Math.max(0, names.length - MAX_HISTORY));
    for (const n of extra) await fs.promises.unlink(path.join(REPORT_DIR, n));
    return extra.length;
}

// limpieza de .tmp huérfanos de una ejecución interrumpida
fs.promises.readdir(REPORT_DIR).then(function (names) {
    return Promise.all(names.filter(function (n) { return /^WAVE_TEST_.*\.json\.tmp$/.test(n); })
        .map(function (n) { return fs.promises.unlink(path.join(REPORT_DIR, n)).catch(function () {}); }));
}).catch(function () { /* el directorio todavía no existe */ });

status('grey', 'listo · dir ' + REPORT_DIR);

globalThis.__WAVE_EXPORT__ = {
    onMsg: function (msg) {
        if (!msg) return;
        if (msg.topic === 'export') startJob('manual');
        else if (msg.topic === 'export_auto') startJob('auto');
        else if (msg.topic === 'dump') { X.manualDump = true; node.send([{ topic: 'dump' }, null, null, null], false); }
        else if (msg.topic === 'wave_test_v1/detail') onDetail(msg.payload);
        else if (msg.topic === 'wave_test_v1/samples') onSamples(msg);
    },
    stop: function () { if (X.job && X.job.timer) clearTimeout(X.job.timer); X.job = null; }
};

func:
// Sólo lectura: guarda el detalle de EVAL / las muestras y atiende las rutas /wave-lab/*.
globalThis.__WAVE_LAB__.onMsg(msg);
return null;

initialize:
// =====================================================================
// WAVE_TEST_V1 · WAVE LAB STORE  (capa de visualización, sólo lectura)
// ---------------------------------------------------------------------
// NO calcula señales ni estadísticas: guarda en memoria lo que WAVE TEST EVAL
// ya publica y lo sirve por HTTP a la página WAVE LAB.
// Entradas:
//   - detalle de EVAL (salida 2, cada 5 s)          topic 'wave_test_v1/detail'
//   - muestras (DUMP) reenviadas por WAVE TEST EXPORT topic 'wave_test_v1/samples'
//   - HTTP: GET /wave-lab/data · POST /wave-lab/reset · GET /wave-lab/export
// Salidas: 1 -> http response · 2 -> WAVE TEST EVAL ({topic:'reset'} / {topic:'dump'})
// Los DUMP sólo se piden mientras alguien mira la página (poll < 20 s) cada 10 s,
// o al pedir EXPORT DATA. Nada de esto toca la ruta de eventos de alta frecuencia.
// =====================================================================
const DUMP_EVERY_MS = 10000;      // refresco de "¿llegamos tarde?" mientras la página está abierta
const VIEW_TTL_MS = 20000;        // la página se considera abierta si pidió datos hace < 20 s
const EXPORT_TIMEOUT_MS = 6000;
const N_EXPORT = 500;             // últimas muestras completas en EXPORT DATA
const N_LATE = 300;               // muestras direccionales cerradas para el perfil promedio
const N_ROWS = 15;                // filas de la tabla "¿llegamos tarde?"
const HEALTH_WINDOW_MS = 60000;   // crecimiento de contadores de salud en el último minuto

const L = {
    detail: null, detailAt: 0,
    late: null, lastDumpReq: 0, lastPoll: 0,
    exportWaiters: [],
    health: []                    // [{t, v:{...}}] últimos ~2 min
};

const H_KEYS = ['late_events', 'pending_dropped', 'horizons_expired', 'invalid_refs', 'n_no_ref'];

function healthValues(d) {
    const c = d.counts, q = d.queue;
    let inv = 0;
    for (const k in c.invalid_ref_by_h) inv += c.invalid_ref_by_h[k];
    for (const k in c.invalid_secondary_by_h) inv += c.invalid_secondary_by_h[k];
    return { late_events: q.late_events, pending_dropped: q.pending_dropped, horizons_expired: q.horizons_expired, invalid_refs: inv, n_no_ref: c.n_no_ref };
}

function onDetail(d) {
    L.detail = d;
    L.detailAt = Date.now();
    const v = healthValues(d);
    // un RESET de EVAL reinicia contadores: la historia de crecimiento también
    const prev = L.health.length ? L.health[L.health.length - 1].v : null;
    if (prev && H_KEYS.some(function (k) { return v[k] < prev[k]; })) L.health = [];
    L.health.push({ t: L.detailAt, v: v });
    while (L.health.length && L.detailAt - L.health[0].t > 2 * HEALTH_WINDOW_MS) L.health.shift();
}

function healthGrowth() {
    if (!L.health.length) return null;
    const last = L.health[L.health.length - 1];
    let base = L.health[0];
    for (const h of L.health) { if (last.t - h.t >= HEALTH_WINDOW_MS) base = h; else break; }
    const o = {};
    for (const k of H_KEYS) o[k] = { value: last.v[k], delta_60s: last.v[k] - base.v[k] };
    return o;
}

// ---------- "¿llegamos tarde?": perfil promedio del mid de Binance alrededor de t0 ----------
// pre_move.binance_mid_move_Xms_bps = (mid(t0)/mid(t0-X) - 1)·1e4  =>  mid(t0-X) relativo a t0 = -pre
// todo firmado por la dirección de WAVE: > 0 = a favor de la señal
const PRE = [[1000, -1000], [500, -500], [250, -250], [100, -100]];
const POST = [['100ms', 100], ['250ms', 250], ['500ms', 500], ['1s', 1000], ['2s', 2000]];

function mean(a) { return a.length ? a.reduce(function (s, x) { return s + x; }, 0) / a.length : null; }
function r3(x) { return x === null || !isFinite(x) ? null : Math.round(x * 1000) / 1000; }

function profile(rows) {
    const pts = [];
    for (const p of PRE) {
        const v = rows.map(function (s) { const m = s.pre_move['binance_mid_move_' + p[0] + 'ms_bps']; return m === null || m === undefined ? null : -m * s.sign; })
            .filter(function (x) { return x !== null; });
        pts.push({ t: p[1], mean: r3(mean(v)), n: v.length });
    }
    pts.push({ t: 0, mean: 0, n: rows.length });
    for (const p of POST) {
        const v = rows.map(function (s) { const f = s.future[p[0]]; return f && f.signed_bps !== null && f.signed_bps !== undefined ? f.signed_bps : null; })
            .filter(function (x) { return x !== null; });
        pts.push({ t: p[1], mean: r3(mean(v)), n: v.length });
    }
    return pts;
}

function onSamples(samples) {
    const now = Date.now();
    if (L.exportWaiters.length) {
        const ws = L.exportWaiters;
        L.exportWaiters = [];
        for (const w of ws) { clearTimeout(w.timer); respondExport(w.msg, samples); }
    }
    const done = samples.filter(function (s) {
        return s.sign !== 0 && s.p0 !== null && s.future && s.future['1s'] && s.future['1s'].signed_bps !== null && s.future['1s'].signed_bps !== undefined;
    }).slice(-N_LATE);
    const strong = done.filter(function (s) { return s.tercile_provisional === 'strong'; });
    const sgn = function (s, w) { const m = s.pre_move['binance_mid_move_' + w + 'ms_bps']; return m === null || m === undefined ? null : r3(m * s.sign); };
    const fut = function (s, k) { const f = s.future[k]; return f ? f.signed_bps : null; };
    L.late = {
        updated_at: now, n: done.length, n_strong: strong.length,
        path_all: profile(done), path_strong: profile(strong),
        rows: done.slice(-N_ROWS).reverse().map(function (s) {
            return { t0: s.t0, direction: s.direction, strength_abs_usd: s.strength_abs_usd, breadth: s.breadth,
                pre100: sgn(s, 100), pre250: sgn(s, 250), pre500: sgn(s, 500),
                post250: fut(s, '250ms'), post500: fut(s, '500ms'), post1s: fut(s, '1s') };
        })
    };
}

function requestDump() {
    L.lastDumpReq = Date.now();
    node.send([null, { topic: 'dump' }], false);
}

// ---------- HTTP ----------
function sendJson(msg, code, obj, extraHeaders) {
    msg.statusCode = code;
    msg.headers = Object.assign({ 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }, extraHeaders || {});
    msg.payload = typeof obj === 'string' ? obj : JSON.stringify(obj);
    node.send([msg, null], false);
}

function currentState(d) {
    const s = d && d.last_samples && d.last_samples.length ? d.last_samples[d.last_samples.length - 1] : null;
    if (!s) return null;
    const b = s.exchanges && s.exchanges.binance;
    return {
        t0: s.t0, direction: s.direction, sign: s.sign,
        strength_abs_usd: s.strength_abs_usd, delta_usd_250ms: s.delta_usd_250ms,
        buy_usd_250ms: s.buy_usd_250ms, sell_usd_250ms: s.sell_usd_250ms, flow_imbalance_250ms: s.flow_imbalance_250ms,
        breadth: s.breadth, active_exchanges: s.active_exchanges,
        mid_binance: s.p0 !== null ? s.p0 : (b ? b.mid : null),
        spread_bps_binance: s.spread_bps_binance,
        imb1_binance: s.book_imbalance ? s.book_imbalance.imb1_binance : null,
        imb10_binance: s.book_imbalance ? s.book_imbalance.imb10_binance : null
    };
}

function onData(msg) {
    const now = Date.now();
    L.lastPoll = now;
    if (now - L.lastDumpReq >= DUMP_EVERY_MS) requestDump();
    const d = L.detail;
    if (!d) { sendJson(msg, 200, { ok: false, reason: 'esperando el primer reporte de WAVE TEST EVAL (<= 5 s)', server_ts: now }); return; }
    sendJson(msg, 200, {
        ok: true, server_ts: now, detail_ts: d.ts, detail_age_ms: now - L.detailAt, uptime_s: d.uptime_s,
        current: currentState(d),
        config: d.config, counts: d.counts, queue: d.queue, strength: d.strength,
        primary: d.primary_binance_mid,
        health: healthGrowth(),
        late: L.late
    });
}

function onReset(msg) {
    // exactamente el mismo mensaje que el inject RESET TEST
    node.send([null, { topic: 'reset' }], false);
    L.health = []; L.late = null;
    sendJson(msg, 200, { ok: true, reset_at: Date.now() });
}

const pad = function (n) { return (n < 10 ? '0' : '') + n; };
function stamp(t) { const d = new Date(t); return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + '_' + pad(d.getHours()) + '-' + pad(d.getMinutes()) + '-' + pad(d.getSeconds()); }

function respondExport(msg, samples) {
    const d = L.detail;
    if (!d) { sendJson(msg, 503, { ok: false, reason: 'todavía no hay reporte de WAVE TEST EVAL' }); return; }
    const now = Date.now();
    const last = samples.slice(-N_EXPORT);
    const body = {
        export_version: 1, source: 'WAVE LAB (descarga desde navegador)',
        generated_at: new Date(now).toISOString(), uptime_s: d.uptime_s, detail_ts: d.ts, detail_iso: d.iso,
        config: d.config, counts: d.counts, queue: d.queue, strength: d.strength,
        primary_binance_mid: d.primary_binance_mid, secondary_median_mid: d.secondary_median_mid,
        baseline_random_direction: d.baseline_random_direction,
        samples_meta: { n: last.length, max: N_EXPORT, first_t0: last.length ? last[0].t0 : null, last_t0: last.length ? last[last.length - 1].t0 : null },
        samples: last
    };
    sendJson(msg, 200, body, { 'Content-Disposition': 'attachment; filename="WAVE_TEST_' + stamp(now) + '.json"' });
}

function onExport(msg) {
    const w = { msg: msg };
    w.timer = setTimeout(function () {
        L.exportWaiters = L.exportWaiters.filter(function (x) { return x !== w; });
        sendJson(msg, 504, { ok: false, reason: 'timeout esperando muestras de WAVE TEST EVAL' });
    }, EXPORT_TIMEOUT_MS);
    L.exportWaiters.push(w);
    requestDump();
}

const timer = setInterval(function () {
    if (Date.now() - L.lastPoll < VIEW_TTL_MS && Date.now() - L.lastDumpReq >= DUMP_EVERY_MS) requestDump();
}, 2000);

globalThis.__WAVE_LAB__ = {
    onMsg: function (msg) {
        if (msg.req && msg.res) {
            const p = (msg.req.path || '').replace(/\/+$/, '');
            const m = (msg.req.method || 'GET').toUpperCase();
            if (p.endsWith('/wave-lab/data') && m === 'GET') onData(msg);
            else if (p.endsWith('/wave-lab/reset') && m === 'POST') onReset(msg);
            else if (p.endsWith('/wave-lab/export') && m === 'GET') onExport(msg);
            else sendJson(msg, 404, { ok: false });
            return;
        }
        if (msg.topic === 'wave_test_v1/detail') onDetail(msg.payload);
        else if (msg.topic === 'wave_test_v1/samples' && Array.isArray(msg.payload)) onSamples(msg.payload);
    },
    stop: function () {
        clearInterval(timer);
        for (const w of L.exportWaiters) clearTimeout(w.timer);
        L.exportWaiters = [];
    }
};
